func testNCMToManyRemoveOpNCMNumeroEcfAliquota(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a NCM
	var b, c, d, e EcfAliquotum

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, ncmDBTypes, false, strmangle.SetComplement(ncmPrimaryKeyColumns, ncmColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*EcfAliquotum{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, ecfAliquotumDBTypes, false, strmangle.SetComplement(ecfAliquotumPrimaryKeyColumns, ecfAliquotumColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	err = a.AddNCMNumeroEcfAliquota(ctx, tx, true, foreigners...)
	if err != nil {
		t.Fatal(err)
	}

	count, err := a.NCMNumeroEcfAliquota().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 4 {
		t.Error("count was wrong:", count)
	}

	err = a.RemoveNCMNumeroEcfAliquota(ctx, tx, foreigners[:2]...)
	if err != nil {
		t.Fatal(err)
	}

	count, err = a.NCMNumeroEcfAliquota().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	if !queries.IsValuerNil(b.NCMNumero) {
		t.Error("want b's foreign key value to be nil")
	}
	if !queries.IsValuerNil(c.NCMNumero) {
		t.Error("want c's foreign key value to be nil")
	}

	if b.R.NCMNumeroNCM != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if c.R.NCMNumeroNCM != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if d.R.NCMNumeroNCM != &a {
		t.Error("relationship to a should have been preserved")
	}
	if e.R.NCMNumeroNCM != &a {
		t.Error("relationship to a should have been preserved")
	}

	if len(a.R.NCMNumeroEcfAliquota) != 2 {
		t.Error("should have preserved two relationships")
	}

	// Removal doesn't do a stable deletion for performance so we have to flip the order
	if a.R.NCMNumeroEcfAliquota[1] != &d {
		t.Error("relationship to d should have been preserved")
	}
	if a.R.NCMNumeroEcfAliquota[0] != &e {
		t.Error("relationship to e should have been preserved")
	}
}

