func testNCMToOneCstpiscofinUsingCstpiscofin(t *testing.T) {
	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var local NCM
	var foreign Cstpiscofin

	seed := randomize.NewSeed()
	if err := randomize.Struct(seed, &local, ncmDBTypes, true, ncmColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize NCM struct: %s", err)
	}
	if err := randomize.Struct(seed, &foreign, cstpiscofinDBTypes, false, cstpiscofinColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize Cstpiscofin struct: %s", err)
	}

	if err := foreign.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	queries.Assign(&local.CstpiscofinsID, foreign.CstpiscofinsID)
	if err := local.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	check, err := local.Cstpiscofin().One(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}

	if !queries.Equal(check.CstpiscofinsID, foreign.CstpiscofinsID) {
		t.Errorf("want: %v, got %v", foreign.CstpiscofinsID, check.CstpiscofinsID)
	}

	ranAfterSelectHook := false
	AddCstpiscofinHook(boil.AfterSelectHook, func(ctx context.Context, e boil.ContextExecutor, o *Cstpiscofin) error {
		ranAfterSelectHook = true
		return nil
	})

	slice := NCMSlice{&local}
	if err = local.L.LoadCstpiscofin(ctx, tx, false, (*[]*NCM)(&slice), nil); err != nil {
		t.Fatal(err)
	}
	if local.R.Cstpiscofin == nil {
		t.Error("struct should have been eager loaded")
	}

	local.R.Cstpiscofin = nil
	if err = local.L.LoadCstpiscofin(ctx, tx, true, &local, nil); err != nil {
		t.Fatal(err)
	}
	if local.R.Cstpiscofin == nil {
		t.Error("struct should have been eager loaded")
	}

	if !ranAfterSelectHook {
		t.Error("failed to run AfterSelect hook for relationship")
	}
}

