	if len(ncmAllColumns) == len(ncmPrimaryKeyColumns) {
		t.Skip("Skipping table with only primary key columns")
	}
	if len(mySQLNCMUniqueColumns) == 0 {
		t.Skip("Skipping table with no unique columns to conflict on")
	}

	seed := randomize.NewSeed()
	var err error
	// Attempt the INSERT side of an UPSERT
	o := NCM{}
	if err = randomize.Struct(seed, &o, ncmDBTypes, false); err != nil {
		t.Errorf("Unable to randomize NCM struct: %s", err)
	}

	ctx := context.Background()
